import{_ as n,K as p,a as o,c as s,ac as t,q as i,b as r,k as l}from"./chunks/framework.BSuaGltH.js";const P=JSON.parse('{"title":"TCP字节流、可靠传输与网络排错","description":"封装寻址、分帧边界、重传窗口、半关闭、超时证据和带宽时延积。","frontmatter":{"title":"TCP字节流、可靠传输与网络排错","description":"封装寻址、分帧边界、重传窗口、半关闭、超时证据和带宽时延积。","showdocs":{"topics":[{"id":"network-principles","title":"计算机网络原理","link":"/topics/network-principles/"}],"kind":"层次与端到端机制","scope":"general","audience":"general","group":"原理与设计","seriesTitle":"计算机网络原理：模型与推演","summary":"封装寻址、分帧边界、重传窗口、半关闭、超时证据和带宽时延积。","status":"active","related":[{"title":"长度前缀分帧与粘包拆包练习","link":"/principles/network-principles/application","kind":"应用分帧推演","scope":"general","audience":"general"},{"title":"计算机网络原理（04735）","link":"/principles/network-principles/internetprinciples","kind":"故障边界与规范","scope":"general","audience":"general"},{"title":"计算机网络原理（04735） · 先建立分层与交换的整体认识至物理与链路：先让相邻节点通信","link":"/principles/network-principles/internetprinciples-part-01","kind":"故障边界与规范","scope":"general","audience":"general"},{"title":"计算机网络原理（04735） · 应用层：从域名到服务至协议参考","link":"/principles/network-principles/internetprinciples-part-03","kind":"故障边界与规范","scope":"general","audience":"general"},{"title":"计算机网络原理（04735） · IP、子网与路由：跨网络送达主机至传输层：端口、可靠交付与连接","link":"/principles/network-principles/internetprinciples-part-02","kind":"故障边界与规范","scope":"general","audience":"general"}],"prev":false,"next":{"text":"长度前缀分帧与粘包拆包练习","link":"/principles/network-principles/application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"长度前缀分帧与粘包拆包练习","link":"/principles/network-principles/application"}},"headers":[],"relativePath":"principles/network-principles/tcp-and-network-diagnosis.md","filePath":"principles/network-principles/tcp-and-network-diagnosis.md"}'),d={name:"principles/network-principles/tcp-and-network-diagnosis.md"};function u(c,e,T,I,g,k){const a=p("Mermaid");return o(),s("div",null,[e[0]||(e[0]=t('<h1 id="tcp字节流、可靠传输与网络排错" tabindex="-1">TCP字节流、可靠传输与网络排错 <a class="header-anchor" href="#tcp字节流、可靠传输与网络排错" aria-label="Permalink to &quot;TCP字节流、可靠传输与网络排错&quot;">​</a></h1><h2 id="part-1" tabindex="-1">协议分层、寻址与TCP字节流 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;协议分层、寻址与TCP字节流 {#part-1}&quot;">​</a></h2><p><span id="part-1-计算机网络原理-问题、表示与约束"></span></p><p>前置：理解字节流、字节序、客户端与服务端；Python 3.10+ 用于四字节长度前缀解码模型，不要求真实网络。教学范围为TCP RFC9293；分层与字节流；Python 3.10+。核对日期2026-10-17。示例未执行，本轮没有安装依赖、生成协议代码、启动服务或浏览器预览。完整文件与输入见<a href="/principles/network-principles/application">长度前缀解码器与拆包练习</a>；推演结论只适用于写明的模型。</p><h3 id="part-1-layer" tabindex="-1">协议分层与封装 <a class="header-anchor" href="#part-1-layer" aria-label="Permalink to &quot;协议分层与封装 {#part-1-layer}&quot;">​</a></h3><p>把订单消息放入TCP字节流，再装入IP包与链路帧，是概念上的封装关系；实际分段大小不必等于应用消息大小。路由器取出IP层信息决定下一跳，并重新封装本跳链路帧。</p>',6)),i(a,{source:"Zmxvd2NoYXJ0IFRECiBBWyLlupTnlKjmtojmga/vvJrorqLljZXlhoXlrrkiXSAtLT4gQlsiVENQ77ya5a2X6IqC5bqP5Y+35LiO56uv5Y+jIl0KIEIgLS0+IENbIklQ77ya5rqQ5LiO55uu55qE5Zyw5Z2AIl0KIEMgLS0+IERbIumTvui3r+W4p++8muacrOi3s01BQ+S4juagoemqjCJdCiBEIC0tPiBFWyLkuIvkuIDot7PlpITnkIblubbph43mlrDlsIHoo4Xpk77ot6/luKciXQo="}),e[1]||(e[1]=r("p",null,"协议分层与封装应区分对等实体的逻辑协议和本机层间服务。应用报文交给传输层，再封装进IP与链路帧；路由器通常转发IP分组，不会替应用解释订单。上层可依赖下层提供的能力，但不能把链路校验当端到端业务正确性。",-1)),e[2]||(e[2]=r("h3",{id:"part-1-address",tabindex:"-1"},[l("地址端口与路由 "),r("a",{class:"header-anchor",href:"#part-1-address","aria-label":'Permalink to "地址端口与路由 {#part-1-address}"'},"​")],-1)),e[3]||(e[3]=r("p",null,"地址端口与路由分别回答到哪台主机、哪个通信端点和下一跳。最长前缀匹配选择路由，端口由传输协议参与分用；同一个数字端口的TCP和UDP是不同空间。DNS解析成功不能证明端口可连，端口可连也不能证明认证通过。",-1)),e[4]||(e[4]=r("h3",{id:"part-1-stream",tabindex:"-1"},[l("TCP为何没有消息边界 "),r("a",{class:"header-anchor",href:"#part-1-stream","aria-label":'Permalink to "TCP为何没有消息边界 {#part-1-stream}"'},"​")],-1)),e[5]||(e[5]=r("p",null,"发送两条消息abc和de，接收方可能先读到a，再读到bcde。TCP只保证字节顺序；长度前缀解码器必须先凑齐头部，再按字节数等待负载，而非把每次recv当成一条消息。",-1)),i(a,{source:"Zmxvd2NoYXJ0IFRECiBBWyLlj5HpgIHvvJphYmMiXSAtLT4gU1si5a2X6IqC5rWBYWJjZGUiXQogQlsi5Y+R6YCB77yaZGUiXSAtLT4gUwogUyAtLT4gUjFbIuesrOS4gOasoeivu+WPlmEiXQogUyAtLT4gUjJbIuesrOS6jOasoeivu+WPlmJjZGUiXQogUjEgLS0+IFBbIuW6lOeUqOe8k+WGsuW5tuaMieWNj+iuruWIhuW4pyJdCiBSMiAtLT4gUAo="}),e[6]||(e[6]=t('<p>TCP为何没有消息边界：它向应用提供有序字节流，发送一次的数据可能分多次读取，多次发送也可能一次读到。分帧由应用完成；本文以四字节大端长度前缀表示UTF-8消息，前缀长度指字节数，不能用字符数替代。</p><h4 id="part-1-来源与适用边界" tabindex="-1">来源与适用边界 <a class="header-anchor" href="#part-1-来源与适用边界" aria-label="Permalink to &quot;来源与适用边界 {#part-1-来源与适用边界}&quot;">​</a></h4><ul><li><a href="https://www.rfc-editor.org/rfc/rfc9293.html" target="_blank" rel="noopener noreferrer">英文官方、作者或规范原文</a>：本专题机制依据；按上述固定版本族阅读。</li><li><a href="https://developer.mozilla.org/zh-CN/docs/Web/HTTP/Overview" target="_blank" rel="noopener noreferrer">中文官方或作者资料</a>：用于术语和讲解交叉核对，冲突以原始规范为准。</li></ul><h2 id="part-2" tabindex="-1">TCP可靠传输、流控与连接关闭 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;TCP可靠传输、流控与连接关闭 {#part-2}&quot;">​</a></h2><p><span id="part-2-计算机网络原理-机制、交互与代价"></span></p><h3 id="part-2-reliability" tabindex="-1">TCP重传与确认含义 <a class="header-anchor" href="#part-2-reliability" aria-label="Permalink to &quot;TCP重传与确认含义 {#part-2-reliability}&quot;">​</a></h3><p>假定首个数据字节序号为100，发出3个字节后接收端期待103，因此ACK为103。如果确认丢失，发送端可能重发相同字节范围，接收端通过序号去重；应用业务提交是此后另一个层次的事件。</p>',7)),i(a,{source:"c2VxdWVuY2VEaWFncmFtCiBwYXJ0aWNpcGFudCBDIGFzIOWPkemAgeerrwogcGFydGljaXBhbnQgUyBhcyDmjqXmlLbnq69UQ1AKIEMtPj5TOiBzZXExMDDvvIwz5a2X6IqCCiBTLS14QzogQUNLMTAz5Lii5aSxCiBDLT4+Uzog6YeN5Y+Rc2VxMTAw77yMM+Wtl+iKggogUy0tPj5DOiBBQ0sxMDPvvIzph43lpI3lrZfoioLkuI3lho3kuqTku5gK"}),e[7]||(e[7]=r("p",null,"TCP重传与确认含义针对序号空间中的字节交付，不证明业务提交。响应丢失时服务可能已扣款，客户端只能知道没有拿到结果，不能因超时就认定未执行。应用需要请求标识与结果查询来处理不确定性。",-1)),e[8]||(e[8]=r("h3",{id:"part-2-flow",tabindex:"-1"},[l("流量控制与拥塞控制 "),r("a",{class:"header-anchor",href:"#part-2-flow","aria-label":'Permalink to "流量控制与拥塞控制 {#part-2-flow}"'},"​")],-1)),e[9]||(e[9]=r("p",null,"简化为以字节计的两个窗口时，允许在途量上限近似取min(rwnd,cwnd)。例如rwnd=64KiB、cwnd=16KiB且已有12KiB未确认，新发送空间最多约4KiB；实际还受发送缓冲、算法和协议细节约束。",-1)),i(a,{source:"Zmxvd2NoYXJ0IFRECiBBWyJyd25k77yaNjRLaULmjqXmlLbog73lipsiXSAtLT4gQ1si5Y+W5YWx5ZCM6ZmQ5Yi2MTZLaUIiXQogQlsiY3duZO+8mjE2S2lC5oul5aGe6ZmQ5Yi2Il0gLS0+IEMKIEMgLS0+IERbIuWHj+WOu+WcqOmAlDEyS2lCIl0KIEQgLS0+IEVbIuWPr+aWsOWinue6pjRLaUIiXQo="}),e[10]||(e[10]=r("p",null,"流量控制与拥塞控制保护不同对象。接收窗口表达接收方缓存能力，拥塞窗口限制在途数据对路径的压力，发送受两者共同限制。增加接收缓存不能必然修复拥塞；公平和吞吐还受RTT、丢包及算法影响。",-1)),e[11]||(e[11]=r("h3",{id:"part-2-close",tabindex:"-1"},[l("连接关闭与半关闭 "),r("a",{class:"header-anchor",href:"#part-2-close","aria-label":'Permalink to "连接关闭与半关闭 {#part-2-close}"'},"​")],-1)),e[12]||(e[12]=r("p",null,"请求方可以结束自己的发送方向后继续读取响应。收到FIN意味着该方向字节结束，接收端还可以发送自己的剩余数据；如果长度头声明10字节却只收8字节就EOF，应判为应用消息截断。",-1)),i(a,{source:""}),e[13]||(e[13]=t('<p>连接关闭与半关闭按方向考虑：一方结束发送，不代表不能继续接收。收到EOF表示字节流该方向结束，若应用帧还剩半个头部或半个负载，应报告截断。连接超时与收到显式关闭也不是相同证据。</p><h4 id="part-2-来源与适用边界" tabindex="-1">来源与适用边界 <a class="header-anchor" href="#part-2-来源与适用边界" aria-label="Permalink to &quot;来源与适用边界 {#part-2-来源与适用边界}&quot;">​</a></h4><ul><li><a href="https://www.rfc-editor.org/rfc/rfc9293.html" target="_blank" rel="noopener noreferrer">英文官方、作者或规范原文</a>：本专题机制依据；按上述固定版本族阅读。</li><li><a href="https://developer.mozilla.org/zh-CN/docs/Web/HTTP/Overview" target="_blank" rel="noopener noreferrer">中文官方或作者资料</a>：用于术语和讲解交叉核对，冲突以原始规范为准。</li></ul><h2 id="part-3" tabindex="-1">网络超时、带宽时延积与排错 <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;网络超时、带宽时延积与排错 {#part-3}&quot;">​</a></h2><p><span id="part-3-计算机网络原理-反例、取舍与原文"></span></p><h3 id="part-3-failure" tabindex="-1">网络超时证据边界 <a class="header-anchor" href="#part-3-failure" aria-label="Permalink to &quot;网络超时证据边界 {#part-3-failure}&quot;">​</a></h3><p>下面的提交已经发生，但客户端只看到超时。安全恢复通常使用同一请求标识查询结果或执行幂等重试；换一个新标识再次提交，可能把一次业务变成两次。仅靠客户端超时日志无法排除另一种情况：原请求根本没到服务端。</p>',7)),i(a,{source:"c2VxdWVuY2VEaWFncmFtCiBwYXJ0aWNpcGFudCBDIGFzIOWuouaIt+errwogcGFydGljaXBhbnQgUyBhcyDmnI3liqHnq68KIEMtPj5TOiDor7fmsYJpZD00MgogUy0+PlM6IOaPkOS6pOS4muWKoee7k+aenAogUy0teEM6IOWTjeW6lOWcqOmAlOS4reS4ouWksQogQy0+PkM6IOi2heaXtu+8jOe7k+aenOacquefpQogQy0+PlM6IOS7pWlkPTQy5p+l6K+i5pei5pyJ57uT5p6cCg=="}),e[14]||(e[14]=r("p",null,"网络超时证据边界是未在期限内观测到结果，可能是请求丢失、处理慢或响应丢失。不能把未知状态替换成失败后直接重试有副作用操作。画出发送、提交、响应三事件，指出哪一步有证据，才能讨论恢复。",-1)),e[15]||(e[15]=r("h3",{id:"part-3-cost",tabindex:"-1"},[l("带宽时延积与队列 "),r("a",{class:"header-anchor",href:"#part-3-cost","aria-label":'Permalink to "带宽时延积与队列 {#part-3-cost}"'},"​")],-1)),e[16]||(e[16]=r("p",null,"100Mbit/s与100ms RTT的乘积为10Mbit，约1.25MB。若在途窗口仅125KB，忽略其他限制时吞吐上限约10Mbit/s；但无界增大缓冲会增加排队，并不能无限提升瓶颈带宽。",-1)),i(a,{source:"Zmxvd2NoYXJ0IExSCiBBWyLlj5HpgIHnqpflj6MiXSAtLT4gQlsi6Lev5b6E5Lit55qE5Zyo6YCU5a2X6IqCIl0KIEIgLS0+IENbIueTtumiiOmYn+WIlyJdCiBDIC0tPiBEWyLmjqXmlLbnq68iXQogRCAtLiAiQUNL57uP6L+HUlRU6L+U5ZueIiAuLT4gQQo="}),e[17]||(e[17]=t('<p>带宽时延积与队列刻画不同成本：链路带宽乘RTT近似填满路径所需在途数据量，过大缓存可能增加排队时延。吞吐高不意味着交互延迟低；应写明测量窗口、负载与分位数，本轮没有网络实测。</p><h3 id="part-3-sources" tabindex="-1">网络规范与旧笔记 <a class="header-anchor" href="#part-3-sources" aria-label="Permalink to &quot;网络规范与旧笔记 {#part-3-sources}&quot;">​</a></h3><p>网络规范与旧笔记以RFC9293约束TCP语义，中文MDN帮助理解应用交互。历史自考网络笔记仍可查分层与交换；本课程不把五层教学模型说成每个实际实现都严格对应五个独立模块。</p><h4 id="part-3-来源与适用边界" tabindex="-1">来源与适用边界 <a class="header-anchor" href="#part-3-来源与适用边界" aria-label="Permalink to &quot;来源与适用边界 {#part-3-来源与适用边界}&quot;">​</a></h4><ul><li><a href="https://www.rfc-editor.org/rfc/rfc9293.html" target="_blank" rel="noopener noreferrer">英文官方、作者或规范原文</a>：本专题机制依据；按上述固定版本族阅读。</li><li><a href="https://developer.mozilla.org/zh-CN/docs/Web/HTTP/Overview" target="_blank" rel="noopener noreferrer">中文官方或作者资料</a>：用于术语和讲解交叉核对，冲突以原始规范为准。</li><li><a href="/principles/network-principles/internetprinciples">相关既有参考</a>：原URL与专业范围保留；历史案例不能自动代表当前实现。</li></ul>',5))])}const h=n(d,[["render",u]]);export{P as __pageData,h as default};
